local FishingTrapMaker = {}
local PRODUCTS = {
    simple_wood_fishing_trap = { name = "Preprosta lesena ribiška vrša", woodCost = 3, ropeCost = 1, time = 3, cost = 50, food = 12, happiness = 1, description = "Preprosta lesena ribiška vrša za ulov rib." },
    willow_woven_trap = { name = "Vrbovapletena vrša", woodCost = 2, leatherCost = 1, ropeCost = 1, time = 5, cost = 130, food = 22, happiness = 1, prestige = 2, description = "Vrbovapletena vrša za trgovce." },
    silver_laced_trap = { name = "Srebrnooplaščena vrša", woodCost = 2, silverCost = 1, leatherCost = 1, ropeCost = 1, time = 8, cost = 320, food = 35, happiness = 2, prestige = 6, description = "Srebrnooplaščena vrša za plemiče." },
    gold_trimmed_trap = { name = "Zlatookrasna vrša", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, ropeCost = 1, time = 12, cost = 760, food = 48, happiness = 3, prestige = 14, description = "Zlatookrasna vrša za visoke plemiče." },
    jewel_set_trap = { name = "Draguljasta vrša", woodCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, ropeCost = 1, jewelCost = 1, time = 16, cost = 1700, food = 62, happiness = 5, prestige = 27, description = "Vrša z draguljem za visoko plemstvo." },
    royal_grand_fishing_trap = { name = "Kraljevski veliki ribiška vrša", woodCost = 4, goldCost = 2, silverCost = 2, leatherCost = 1, ropeCost = 1, jewelCost = 2, pearlCost = 2, time = 23, cost = 3700, food = 85, happiness = 12, prestige = 58, description = "Velika kraljevska ribiška vrša z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    trap_workshop = { name = "Vršarska delavnica", cost = { gold = 250, wood = 140, stone = 120, rope = 6, leather = 4 }, upkeep = 5, qualityBonus = 5 },
    fishing_loft = { name = "Ribiška podstrešje", cost = { gold = 920, wood = 280, stone = 240, silver = 6, leather = 6 }, upkeep = 21, qualityBonus = 18 },
    master_trap_atelier = { name = "Mojstrski vršarski atelje", cost = { gold = 2650, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 61, qualityBonus = 30 },
    royal_fishery_palace = { name = "Kraljevska ribiška palača", cost = { gold = 11200, wood = 580, stone = 760, gold = 72, jewel = 18 }, upkeep = 225, qualityBonus = 55, prestigeBonus = 50 },
}
FishingTrapMaker.woodStock = 18; FishingTrapMaker.ropeStock = 10; FishingTrapMaker.leatherStock = 10; FishingTrapMaker.silverStock = 6; FishingTrapMaker.goldStock = 6; FishingTrapMaker.jewelStock = 4; FishingTrapMaker.pearlStock = 4
FishingTrapMaker.productStock = {}; FishingTrapMaker.buildings = {}; FishingTrapMaker.maker = nil; FishingTrapMaker.activeMaking = {}; FishingTrapMaker.totalProducts = 0; FishingTrapMaker.dayTimer = 0
function FishingTrapMaker.init() FishingTrapMaker.woodStock=18; FishingTrapMaker.ropeStock=10; FishingTrapMaker.leatherStock=10; FishingTrapMaker.silverStock=6; FishingTrapMaker.goldStock=6; FishingTrapMaker.jewelStock=4; FishingTrapMaker.pearlStock=4; FishingTrapMaker.productStock={}; FishingTrapMaker.buildings={}; FishingTrapMaker.maker=nil; FishingTrapMaker.activeMaking={}; FishingTrapMaker.totalProducts=0; FishingTrapMaker.dayTimer=0; print("[FishingTrapMaker] Royal Fishing Trap Maker System initialized (6 products, 4 buildings)") end
function FishingTrapMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; FishingTrapMaker.maker={name=n or ("Vršar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vršar najet: %s (spretnost: %d)",FishingTrapMaker.maker.name,s),"success") end; return true end
function FishingTrapMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function FishingTrapMaker.build(id) local ok,e=FishingTrapMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(FishingTrapMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function FishingTrapMaker.getQualityBonus() local b=0; for _,bd in ipairs(FishingTrapMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function FishingTrapMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and FishingTrapMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ropeCost and FishingTrapMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.leatherCost and FishingTrapMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and FishingTrapMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and FishingTrapMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and FishingTrapMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and FishingTrapMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #FishingTrapMaker.buildings==0 then return false,"Potrebna vršarska delavnica" end; if not FishingTrapMaker.maker then return false,"Potreben vršar" end; return true end
function FishingTrapMaker.make(pt,qty) qty=qty or 1; local ok,e=FishingTrapMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then FishingTrapMaker.woodStock=FishingTrapMaker.woodStock-d.woodCost*qty end; if d.ropeCost then FishingTrapMaker.ropeStock=FishingTrapMaker.ropeStock-d.ropeCost*qty end; if d.leatherCost then FishingTrapMaker.leatherStock=FishingTrapMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then FishingTrapMaker.silverStock=FishingTrapMaker.silverStock-d.silverCost*qty end; if d.goldCost then FishingTrapMaker.goldStock=FishingTrapMaker.goldStock-d.goldCost*qty end; if d.jewelCost then FishingTrapMaker.jewelStock=FishingTrapMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then FishingTrapMaker.pearlStock=FishingTrapMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if FishingTrapMaker.maker then t=math.max(1,t-math.floor(FishingTrapMaker.maker.skill/14)) end; table.insert(FishingTrapMaker.activeMaking,{id="fishingtrap_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=d.food or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pletenje: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function FishingTrapMaker.completeMaking(m) local q=1.0+(FishingTrapMaker.getQualityBonus()/100); if FishingTrapMaker.maker then q=q+(FishingTrapMaker.maker.skill/140) end; q=math.min(2.5,q); FishingTrapMaker.productStock[m.productType]=(FishingTrapMaker.productStock[m.productType] or 0)+m.quantity; FishingTrapMaker.totalProducts=FishingTrapMaker.totalProducts+m.quantity; if m.food>0 and _G.state then _G.state.food=(_G.state.food or 0)+m.food end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if FishingTrapMaker.maker then FishingTrapMaker.maker.itemsMade=FishingTrapMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then FishingTrapMaker.maker.skill=math.min(100,FishingTrapMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Vrša izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"fishingtrap.completed",{productName=m.productName,food=m.food,prestige=m.prestige,happiness=m.happiness}) end end
function FishingTrapMaker.update(dt) if not _G.state then return end; FishingTrapMaker.dayTimer=FishingTrapMaker.dayTimer+dt; if FishingTrapMaker.dayTimer>=30 then FishingTrapMaker.dayTimer=0; for i=#FishingTrapMaker.activeMaking,1,-1 do local m=FishingTrapMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then FishingTrapMaker.completeMaking(m); table.remove(FishingTrapMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(FishingTrapMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if FishingTrapMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function FishingTrapMaker.getStats() return {woodStock=FishingTrapMaker.woodStock,ropeStock=FishingTrapMaker.ropeStock,leatherStock=FishingTrapMaker.leatherStock,silverStock=FishingTrapMaker.silverStock,goldStock=FishingTrapMaker.goldStock,jewelStock=FishingTrapMaker.jewelStock,pearlStock=FishingTrapMaker.pearlStock,productStock=FishingTrapMaker.productStock,numBuildings=#FishingTrapMaker.buildings,hasMaker=FishingTrapMaker.maker~=nil,makerName=FishingTrapMaker.maker and FishingTrapMaker.maker.name or "—",makerSkill=FishingTrapMaker.maker and FishingTrapMaker.maker.skill or 0,activeMaking=#FishingTrapMaker.activeMaking,totalProducts=FishingTrapMaker.totalProducts} end
return FishingTrapMaker
